import{_ as a,o as r,c as i,a3 as t}from"./chunks/framework.DEy3KOfk.js";const h=JSON.parse('{"title":"@pumpkin-plugins/terrain","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/terrain/README.md"},"headers":[],"relativePath":"tools/terrain/README.md","filePath":"tools/terrain/README.md","lastUpdated":1791384853000}'),n={name:"tools/terrain/README.md"};function s(o,e,p,d,l,c){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="pumpkin-plugins-terrain" tabindex="-1">@pumpkin-plugins/terrain <a class="header-anchor" href="#pumpkin-plugins-terrain" aria-label="Permalink to &quot;@pumpkin-plugins/terrain&quot;">​</a></h1><p>MIT-licensed terrain capture primitives and chunk access contracts for Pumpkin plugins. The package is independent of Pumpkin APIs and wire protocols, so plugins can provide their own host adapters and output encoders.</p><p><code>TerrainCapture</code> samples rectangular regions within a caller-provided per-step budget, groups material runs into columns, and can skip empty blocks above a height bound.</p><p><code>AdaptiveWorkBudget</code> scales an incremental work limit using rolling server MSPT and measured work cost, while honoring a caller-provided ceiling. It is suitable for terrain capture or other shared server-side workloads that should use spare tick time and back off under load.</p><p><code>ChunkLoader</code> and <code>TerrainGenerator</code> define provider interfaces. <code>acquireChunk</code> checks already-loaded chunks, requests saved chunk loading, and requests generation when the saved chunk is missing or loading is unavailable. Exported unavailable providers make platforms without these capabilities explicit.</p><p>This package is internal to the repository and is not published to npm. See the <a href="./../../docs/code-style">code style guide</a> and <a href="https://filiphsps.github.io/pumpkin-plugins/api/tools/@pumpkin-plugins/terrain/" target="_blank" rel="noreferrer">API reference</a>.</p>',6)])])}const m=a(n,[["render",s]]);export{h as __pageData,m as default};
